cd /testbed && python3 - <<'PY'
from pathlib import Path
import difflib
import subprocess
path = Path('processing/src/test/java/org/apache/druid/query/groupby/GroupByQueryQueryToolChestTest.java')
old = path.read_text()
new = old.replace('import org.apache.druid.java.util.common.granularity.Granularities;\n', 'import org.apache.druid.java.util.common.granularity.Granularities;\nimport org.apache.druid.java.util.common.granularity.Granularity;\n', 1)
new = new.replace('import org.apache.druid.query.aggregation.LongSumAggregatorFactory;\n', 'import org.apache.druid.query.aggregation.LongSumAggregatorFactory;\nimport org.apache.druid.query.aggregation.PostAggregator;\n', 1)
marker = '  @Test\n  public void testMultiColumnCacheStrategy() throws Exception\n'
assert new.count(marker) == 1
addition = '''  @Test
  public void testResultLevelCacheWithPostAggregators() throws Exception
  {
    final List<PostAggregator> postAggregators = ImmutableList.of(
        new ExpressionPostAggregator("a2", "rows * 2", null, null, TestExprMacroTable.INSTANCE),
        new ExpressionPostAggregator("a3", "rows * 3", null, null, TestExprMacroTable.INSTANCE),
        new ExpressionPostAggregator("a4", "rows * 4", null, null, TestExprMacroTable.INSTANCE)
    );
    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();

    for (Granularity granularity : ImmutableList.of(Granularities.ALL, Granularities.DAY)) {
      for (int postAggregatorCount = 0; postAggregatorCount <= postAggregators.size(); postAggregatorCount++) {
        final GroupByQuery query = GroupByQuery.builder()
            .setDataSource(QueryRunnerTestHelper.DATA_SOURCE)
            .setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD)
            .setDimensions(DefaultDimensionSpec.of("channel"), DefaultDimensionSpec.of("cityName"))
            .setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT)
            .setPostAggregatorSpecs(postAggregators.subList(0, postAggregatorCount))
            .setGranularity(granularity)
            .build();
        final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
            new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
        final ResultRow fullResult = query.getResultRowHasTimestamp()
                                     ? ResultRow.of(123L, "#en.wikipedia", null, 10516, 21032, 31548, 42064)
                                     : ResultRow.of("#en.wikipedia", null, 10516, 21032, 31548, 42064);
        final ResultRow expectedResult = ResultRow.of(
            Arrays.copyOf(fullResult.getArray(), query.getResultRowSizeWithPostAggregators())
        );
        final Object preparedValue = strategy.prepareForCache(true).apply(expectedResult);
        final Object fromCacheValue = objectMapper.readValue(
            objectMapper.writeValueAsBytes(preparedValue),
            strategy.getCacheObjectClazz()
        );

        Assert.assertEquals(expectedResult, strategy.pullFromCache(true).apply(fromCacheValue));
      }
    }
  }

'''
new = new.replace(marker, addition + marker, 1)
diff = ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile=str(path), tofile=str(path)))
subprocess.run(['patch', '-p0'], input=diff, text=True, check=True)
PY
